  warning: "#ffb90e",
  danger: "#ff736d",
  controlOn: "#e8e8e8",
  controlGlyph: "#141414",
  controlTrack: "#353535",
  controlThumb: "#f5f5f5",
  controlThumbOn: "#141414",
  controlFill: "#868686",
